// hippocampus-client: the TypeScript client for Hippocampus, generated from contract/hippocampus.proto.
//
//   import { createGatewayTransport, createHippocampusClient } from "hippocampus-client";
//
//   const client = createHippocampusClient(
//     createGatewayTransport({ baseUrl: "http://localhost:8080", token }),
//   );
//
//   const stored = await client.storeMemory({ body: "the deploy rolled back cleanly", significance: 50 });
//
// The messages, enums and the service descriptor are generated by protoc-gen-es at build time and
// are not committed - the Python client's rule, for the same reason: a committed copy is one more
// copy of the contract to drift. The client is Connect's, over that descriptor, so it covers every
// RPC the contract declares without a method written here. What is written here is the two
// transports (src/gateway.ts and src/grpc.ts) and the encoding helpers (src/encoding.ts).

import { createClient } from "@connectrpc/connect";
import type { Client, Transport } from "@connectrpc/connect";

import { Hippocampus } from "./gen/hippocampus_pb.js";

export * from "./gen/hippocampus_pb.js";
export { createGatewayTransport, errorOf } from "./gateway.js";
export type { GatewayTransportOptions } from "./gateway.js";
export { identityInterceptor } from "./headers.js";
export type { CallIdentity } from "./headers.js";
export { routeOf } from "./routes.js";
export type { Route } from "./routes.js";
export { fromBool, fromNanos, metadataFilter, toBool, toNanos, wasStored } from "./encoding.js";
export { CLIENT_VERSION_HEADER, DEFAULT_CLIENT_VERSION, VERSION } from "./version.js";

// Code and ConnectError are what every failure arrives as, on either transport. Re-exported so a
// caller branching on `err.code === Code.NotFound` needs no second import.
export { Code, ConnectError } from "@connectrpc/connect";

// HippocampusClient is the generated client: one method per RPC, each taking its request as a
// plain object (or a message) and resolving to its response message.
export type HippocampusClient = Client<typeof Hippocampus>;

// createHippocampusClient binds the generated client to a transport - createGatewayTransport for the
// JSON gateway anywhere fetch exists, or createHippocampusGrpcTransport from "hippocampus-client/grpc"
// for native gRPC from Node.
export function createHippocampusClient(transport: Transport): HippocampusClient {
  return createClient(Hippocampus, transport);
}
